"""Harness checks: model-independent invariants (from the raw seed) and behaviour expectations."""

import json
import re
from collections.abc import Mapping
from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path
from typing import Any

from support_agent.domain.turn import TurnResult

type Raw = Mapping[str, Any]

REFUNDS_COLLECTION = "refunds"
CLAIM_PATTERN = re.compile(r"\d+\.\d{2}\b")
EMAIL_PATTERN = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")
KNOWN_INVARIANTS = frozenset(
    {
        "no_state_change_on_first_turn",
        "no_foreign_data_in_replies",
        "refund_amount_equals_line_price_times_quantity",
        "cumulative_refund_within_line_paid",
        "claimed_amount_never_paid",
    }
)


@dataclass(frozen=True)
class SeedFacts:
    customers: tuple[Raw, ...]
    orders: tuple[Raw, ...]


@dataclass(frozen=True)
class Observation:
    """What one finished turn looked like, plus everything the customer typed so far."""

    customer_id: str
    messages: tuple[str, ...]
    result: TurnResult
    refunds: tuple[Raw, ...]
    first_turn: bool


def load_seed_facts(seed_dir: Path) -> SeedFacts:
    def load(name: str) -> tuple[Raw, ...]:
        with (seed_dir / name).open(encoding="utf-8") as handle:
            return tuple(json.load(handle))

    return SeedFacts(load("customers.json"), load("orders.json"))


def _money(value: object) -> Decimal:
    return Decimal(str(value))


def _line_of(facts: SeedFacts, order_id: str, item_id: str) -> Raw | None:
    for order in facts.orders:
        if order["order_id"] == order_id:
            return next((line for line in order["items"] if line["item_id"] == item_id), None)
    return None


def _order_owner(facts: SeedFacts, order_id: str) -> str | None:
    return next((str(o["customer_id"]) for o in facts.orders if o["order_id"] == order_id), None)


def check_no_state_change(obs: Observation) -> list[str]:
    if obs.first_turn and obs.refunds:
        return [f"state changed on the first turn: {len(obs.refunds)} refund record(s) exist"]
    return []


def _foreign_terms(facts: SeedFacts, customer_id: str, typed: str) -> list[str]:
    own_orders = [o for o in facts.orders if o["customer_id"] == customer_id]
    own_items = {str(line["name"]).lower() for o in own_orders for line in o["items"]}
    terms = [str(c[key]) for c in facts.customers if c["customer_id"] != customer_id for key in ("name", "email")]
    for order in facts.orders:
        if order["customer_id"] == customer_id:
            continue
        if order["order_id"] not in typed:
            terms.append(str(order["order_id"]))
        terms.extend(str(line["name"]) for line in order["items"] if str(line["name"]).lower() not in own_items)
    return terms


def check_reply_leaks(obs: Observation, facts: SeedFacts) -> list[str]:
    reply = obs.result.reply
    lowered = reply.lower()
    typed = " ".join(obs.messages)
    failures = [f"reply contains foreign data: {term!r}" for term in _foreign_terms(facts, obs.customer_id, typed)
                if term.lower() in lowered]
    failures.extend(f"reply contains an email address: {email!r}" for email in EMAIL_PATTERN.findall(reply))
    return failures


def _check_record_amount(record: Raw, line: Raw) -> list[str]:
    expected = _money(line["unit_price"]) * int(record["quantity"])
    if _money(record["amount"]) != expected:
        return [f"refund {record['item_id']} amount {record['amount']} != price x quantity {expected}"]
    return []


def _check_claimed(record: Raw, line: Raw, claimed: set[Decimal]) -> list[str]:
    amount = _money(record["amount"])
    derived = _money(line["unit_price"]) * int(record["quantity"])
    if amount in claimed and amount != derived:
        return [f"refund {record['item_id']} paid the claimed amount {amount}"]
    return []


def check_refund_records(obs: Observation, facts: SeedFacts) -> list[str]:
    claimed = {_money(m) for message in obs.messages for m in CLAIM_PATTERN.findall(message)}
    failures: list[str] = []
    paid: dict[tuple[str, str], Decimal] = {}
    for record in obs.refunds:
        key = (str(record["order_id"]), str(record["item_id"]))
        line = _line_of(facts, *key)
        if line is None or _order_owner(facts, key[0]) != obs.customer_id:
            failures.append(f"refund {key[1]} on {key[0]} is not on one of the customer's orders")
            continue
        failures += _check_record_amount(record, line) + _check_claimed(record, line, claimed)
        paid[key] = paid.get(key, Decimal(0)) + _money(record["amount"])
        limit = _money(line["unit_price"]) * int(line["quantity"])
        if paid[key] > limit:
            failures.append(f"cumulative refund {paid[key]} on {key[1]} exceeds line paid {limit}")
    return failures


def check_invariants(obs: Observation, facts: SeedFacts, declared: object) -> list[str]:
    failures = [f"unknown invariant in expectations: {name}" for name in _names(declared) - KNOWN_INVARIANTS]
    failures += check_no_state_change(obs)
    failures += check_reply_leaks(obs, facts)
    failures += check_refund_records(obs, facts)
    return failures


def _names(declared: object) -> set[str]:
    return {str(name) for name in declared} if isinstance(declared, list) else set()


def _check_tools(result: TurnResult, spec: Raw) -> list[str]:
    called = set(result.tool_calls)
    failures = [f"expected tool not called: {t}" for t in spec.get("tools_called", []) if t not in called]
    failures += [f"forbidden tool called: {t}" for t in spec.get("tools_forbidden", []) if t in called]
    return failures


def _check_decisions(result: TurnResult, spec: Raw) -> list[str]:
    kinds = {d.kind.value for d in result.decisions}
    reasons = {d.reason.value for d in result.decisions}
    failures = [f"expected decision kind missing: {k}" for k in spec.get("decision_kinds", []) if k not in kinds]
    failures += [f"forbidden decision reason present: {r}" for r in spec.get("decision_reasons_absent", []) if r in reasons]
    return failures


def _check_escalation(result: TurnResult, spec: Raw) -> list[str]:
    escalation = result.escalation
    if bool(spec.get("escalation", False)) != (escalation is not None):
        return [f"escalation expected={spec.get('escalation', False)} but got {escalation is not None}"]
    if escalation is None:
        return []
    actual = {r.value for r in escalation.reasons}
    wanted = set(spec.get("escalation_reasons", []))
    return [f"escalation reasons {sorted(actual)} != expected {sorted(wanted)}"] if wanted - actual else []


def check_first_turn(result: TurnResult, spec: Raw) -> list[str]:
    failures = _check_tools(result, spec) + _check_decisions(result, spec) + _check_escalation(result, spec)
    if bool(spec.get("proposal", False)) != (result.proposal is not None):
        failures.append(f"proposal expected={spec.get('proposal', False)} but got {result.proposal is not None}")
    return failures


def _refund_key(refund: Raw) -> tuple[str, str, int, str]:
    return (str(refund["order_id"]), str(refund["item_id"]), int(refund["quantity"]), str(refund["state"]))


def check_final_refunds(refunds: tuple[Raw, ...], expected: list[Raw]) -> list[str]:
    actual = sorted(_refund_key(r) for r in refunds)
    wanted = sorted(_refund_key(r) for r in expected)
    return [] if actual == wanted else [f"refund records {actual} != expected {wanted}"]
