"""Scenario harness: fresh environment and service per scenario, invariant and behaviour checks, reports."""

import itertools
import json
from collections.abc import Callable, Mapping
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

from mock_env import SEED_DIR, MockCommerceEnv
from support_agent.adapters.audit_log import InMemoryAuditLog
from support_agent.application.ports import ModelClient
from support_agent.composition import build_service
from support_agent.domain.ids import ConversationId, CustomerId
from support_agent.domain.turn import SupportRequest, TurnResult
from support_agent.harness_checks import (
    REFUNDS_COLLECTION,
    Observation,
    SeedFacts,
    check_final_refunds,
    check_first_turn,
    check_invariants,
    load_seed_facts,
)
from support_agent.application.service import SupportService  # noqa: I001

PROJECT_ROOT = Path(__file__).resolve().parents[2]
DEFAULT_SEED_DIR = SEED_DIR
DEFAULT_SCENARIOS = PROJECT_ROOT / "data" / "scenarios.json"
DEFAULT_EXPECTATIONS = PROJECT_ROOT / "data" / "expectations.json"
REPLY_WIDTH = 70
NO_STATE_CHANGE = "none"
NO_ESCALATION = "none"
TABLE_HEADERS = ("scenario", "turn", "reply", "tools", "decisions", "state change", "result")

type Raw = Mapping[str, Any]


@dataclass(frozen=True)
class TurnReport:
    scenario_id: str
    turn_label: str
    reply: str
    tools: tuple[str, ...]
    decisions: tuple[str, ...]
    state_change: str
    escalation: str
    failures: tuple[str, ...]

    @property
    def passed(self) -> bool:
        return not self.failures


@dataclass(frozen=True)
class HarnessReport:
    turns: tuple[TurnReport, ...]

    @property
    def passed(self) -> bool:
        return all(turn.passed for turn in self.turns)


def _read_json(path: Path) -> Any:
    with path.open(encoding="utf-8") as handle:
        return json.load(handle)


def _describe_refund(refund: Raw) -> str:
    return f"refund {refund['state']} {refund['item_id']} x{refund['quantity']}"


def _state_change(before: int, refunds: tuple[Raw, ...]) -> str:
    new = refunds[before:]
    return "; ".join(_describe_refund(r) for r in new) if new else NO_STATE_CHANGE


def _escalation_label(result: TurnResult) -> str:
    if result.escalation is None:
        return NO_ESCALATION
    return ",".join(reason.value for reason in result.escalation.reasons)


def _report(scenario_id: str, label: str, result: TurnResult, change: str, failures: list[str]) -> TurnReport:
    decisions = tuple(f"{d.kind.value}:{d.reason.value}" for d in result.decisions)
    return TurnReport(
        scenario_id, label, result.reply, tuple(result.tool_calls), decisions, change,
        _escalation_label(result), tuple(failures),
    )  # fmt: skip


class _ScenarioRun:
    """One scenario: reset state, play the turns, collect reports."""

    def __init__(self, seed_dir: Path, facts: SeedFacts, model: ModelClient) -> None:
        self._facts = facts
        self._env = MockCommerceEnv(seed_dir)
        counter = itertools.count(1)
        self._service: SupportService = build_service(
            self._env, model, audit_log=InMemoryAuditLog(), new_id=lambda: f"id-{next(counter)}"
        )
        self._messages: list[str] = []

    def refunds(self) -> tuple[Raw, ...]:
        return tuple(self._env.records(REFUNDS_COLLECTION))

    def turn(self, scenario: Raw, label: str, message: str, expectations: Raw | None) -> tuple[TurnReport, TurnResult]:
        before = len(self.refunds())
        customer = str(scenario["authenticated_customer_id"])
        self._messages.append(message)
        result = self._service.handle(
            SupportRequest(CustomerId(customer), ConversationId(str(scenario["scenario_id"])), message)
        )
        refunds = self.refunds()
        obs = Observation(customer, tuple(self._messages), result, refunds, first_turn=len(self._messages) == 1)
        declared = (expectations or {}).get("invariants", [])
        failures = check_invariants(obs, self._facts, declared)
        return _report(str(scenario["scenario_id"]), label, result, _state_change(before, refunds), failures), result


def _run_scenario(seed_dir: Path, facts: SeedFacts, model: ModelClient, scenario: Raw, expected: Raw) -> list[TurnReport]:
    run = _ScenarioRun(seed_dir, facts, model)
    behaviour = expected.get("behaviour", {})
    first, result = run.turn(scenario, "request", str(scenario["message"]), expected)
    first = _with_failures(first, check_first_turn(result, behaviour.get("first_turn", {})))
    reports = [first]
    follow = behaviour.get("follow_up")
    if follow:
        second, _ = run.turn(scenario, str(follow["label"]), str(follow["message"]), expected)
        reports.append(second)
    final = _with_failures(reports[-1], check_final_refunds(run.refunds(), behaviour.get("final_refunds", [])))
    return [*reports[:-1], final]


def _with_failures(report: TurnReport, extra: list[str]) -> TurnReport:
    return TurnReport(
        report.scenario_id, report.turn_label, report.reply, report.tools, report.decisions,
        report.state_change, report.escalation, (*report.failures, *extra),
    )  # fmt: skip


def run_harness(
    seed_dir: Path,
    scenarios_path: Path,
    expectations_path: Path,
    model_factory: Callable[[], ModelClient],
) -> HarnessReport:
    facts = load_seed_facts(seed_dir)
    expectations: Raw = _read_json(expectations_path)
    turns: list[TurnReport] = []
    for scenario in _read_json(scenarios_path):
        expected = expectations.get(scenario["scenario_id"])
        if expected is None:
            turns.append(_missing_expectations(str(scenario["scenario_id"])))
            continue
        turns += _run_scenario(seed_dir, facts, model_factory(), scenario, expected)
    return HarnessReport(tuple(turns))


def _missing_expectations(scenario_id: str) -> TurnReport:
    failure = (f"no expectations for {scenario_id}",)
    return TurnReport(scenario_id, "-", "", (), (), NO_STATE_CHANGE, NO_ESCALATION, failure)


def _truncate(text: str, width: int = REPLY_WIDTH) -> str:
    flat = " ".join(text.split())
    return flat if len(flat) <= width else flat[: width - 3] + "..."


def _row(turn: TurnReport) -> tuple[str, ...]:
    outcome = "PASS" if turn.passed else "FAIL: " + "; ".join(turn.failures)
    return (
        turn.scenario_id, turn.turn_label, _truncate(turn.reply), ",".join(turn.tools) or "-",
        ",".join(turn.decisions) or "-", turn.state_change, outcome,
    )  # fmt: skip


def render_table(report: HarnessReport) -> str:
    rows = [TABLE_HEADERS, *(_row(turn) for turn in report.turns)]
    widths = [max(len(row[i]) for row in rows) for i in range(len(TABLE_HEADERS))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths, strict=True)).rstrip() for row in rows]
    lines.insert(1, "  ".join("-" * width for width in widths))
    return "\n".join(lines)


def render_json(report: HarnessReport) -> str:
    payload = {"passed": report.passed, "turns": [{**asdict(turn), "passed": turn.passed} for turn in report.turns]}
    return json.dumps(payload, ensure_ascii=False, indent=2)
